const EXPECTED_SOURCE_PATHS = Object.freeze(["packages/core/src/ir/semantics/internal-effect-machine-helper-state.ts","packages/core/src/ir/semantics/semantic-clone.ts","packages/core/src/ir/semantics/semantic-env-ownership.ts","packages/core/src/ir/semantics/semantic-env.ts"]);
const EXPECTED_COMPILED_PATHS = Object.freeze(["ir/semantics/internal-effect-machine-helper-state.js","ir/semantics/semantic-clone.js","ir/semantics/semantic-env-ownership.js","ir/semantics/semantic-env.js"]);

function exactRows(rows, expectedPaths) {
  return (
    Array.isArray(rows) &&
    rows.length === expectedPaths.length &&
    rows.every((row, index) =>
      row?.claim === CLAIM &&
      row.path === expectedPaths[index] &&
      /^[0-9a-f]{64}$/u.test(row.currentDigest) &&
      /^[0-9a-f]{64}$/u.test(row.expectedDigest) &&
      Array.isArray(row.replacements) &&
      row.replacements.length > 0
    )
  );
}

export function validateEnvironmentQuarantineHistoricalTransition({
  transition = ENVIRONMENT_QUARANTINE_HISTORICAL_TRANSITION,
  sourceReconstructions = POST_ENVIRONMENT_QUARANTINE_SOURCE_RECONSTRUCTIONS,
  compiledReconstructions = POST_ENVIRONMENT_QUARANTINE_COMPILED_RECONSTRUCTIONS,
} = {}) {
  if (
    transition?.claim !== CLAIM ||
    transition.predecessorCommit !== PREDECESSOR_COMMIT ||
    transition.successorCommit !== SUCCESSOR_COMMIT ||
    JSON.stringify(transition.sourceManifest) !== "{\"count\":4,\"digest\":\"c8c2a4e154d9571c3704b3769b907ba37399ef5808c7e71760197e285a6a295f\"}" ||
    JSON.stringify(transition.compiledManifest) !== "{\"count\":4,\"digest\":\"f8478cce856b95edcbf6e69833106ac742ab21ca300cc693d30b7f5cf115100e\"}" ||
    JSON.stringify(transition.sourceEndpoints) !== "{\"predecessor\":\"f1fb3b68bd22f8590c599578388c32ea38f6be55c800a5dd02f3ca67ee03a28f\",\"successor\":\"fd0edfb5ddfcbbe302c86b3c9468fd83d418deb58f1b0952b019b34523fc121c\"}" ||
    JSON.stringify(transition.compiledEndpoints) !== "{\"predecessor\":\"87e7ae996acb96a7b374f2b9dade47e88e95cffc8fdb480051385830e4a3b04c\",\"successor\":\"4dc3b9195375cfb39d3f7855bb951c62506be72cd2e85444fabdc10b1b18d68a\"}" ||
    JSON.stringify(transition.compiledInventory?.predecessor) !== "{\"count\":317,\"digest\":\"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67\"}" ||
    JSON.stringify(transition.compiledInventory?.successor) !== "{\"count\":317,\"digest\":\"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67\"}" ||
    !exactRows(sourceReconstructions, EXPECTED_SOURCE_PATHS) ||
    !exactRows(compiledReconstructions, EXPECTED_COMPILED_PATHS)
  ) {
    throw new TypeError('environment quarantine historical transition immutable identity changed');
  }
  return true;
}
